			.firstOrNull()
			?: throw SSLHandshakeException("no server aliases for $keyType")

	return getCertificateChain(alias).toList()
}

private fun X509KeyManager.clientCertificatesOrNull(keyType: String): List<X509Certificate>? {
	val alias =
