class AsyncRequestBody : RequestBody() {
	private val requestBodySinks: BlockingQueue<BufferedSink> = LinkedBlockingQueue()

	override fun contentType(): MediaType? = null

	override fun writeTo(sink: BufferedSink) {
		requestBodySinks.add(sink)
	}

	override fun isDuplex(): Boolean = true

	@Throws(InterruptedException::class)
	fun takeSink(): BufferedSink = requestBodySinks.poll(5, SECONDS) ?: throw AssertionError("no sink to take")

	fun assertNoMoreSinks() {
		assertTrue(requestBodySinks.isEmpty())
	}
}

public override fun close() {
	if (closed) return
	closed = true

	if (!started) return // Nothing to shut down.
	val serverSocket = this.serverSocket ?: return // If this is null, start() must have failed.

	// Cause acceptConnections() to break out.
	serverSocket.closeQuietly()

	// Await shutdown.
	for (queue in taskRunner.activeQueues()) {
		if (!queue.idleLatch().await(5, TimeUnit.SECONDS)) {
			throw AssertionError("Gave up waiting for queue to shut down")
		}
	}
	taskRunnerBackend.shutdown()
}

